"""Bounded offline P06 workbench. Original artwork/captures are read, never edited."""
from __future__ import annotations

import argparse
import base64
import io
import json
from pathlib import Path

from PIL import Image, ImageOps

from pass06_environment_common import ROOT, PACKAGE, REVISION, VIEWS, ARCHIVE_SHA, load_package, read, sha

REPORT_ID = "grafik_20261101_pass06_environment_env06"
OUTPUT = ROOT / "docs/reports/STERNENBUERGERCHEN_GRAFIK_2026-11-01.html"


def derivative(path: Path, maximum: int, quality: int) -> str:
    with Image.open(path) as original:
        image = ImageOps.exif_transpose(original).convert("RGB")
        image.thumbnail((maximum, maximum), Image.Resampling.LANCZOS)
        stream = io.BytesIO()
        image.save(stream, "WEBP", quality=quality, method=5)
    return "data:image/webp;base64," + base64.b64encode(stream.getvalue()).decode("ascii")


def prepare_data(pack: dict) -> dict:
    references = read(PACKAGE / "reference_manifest.json")["current_user_references"]
    assets = []

    def add(identifier, path, title, group, status, description, **extra):
        source = ROOT / path
        with Image.open(source) as image:
            dimensions = list(image.size)
        assets.append({"id": identifier, "path": path, "title": title, "group": group,
                       "status": status, "description": description, "sha256": sha(source),
                       "dimensions": dimensions, "thumb": derivative(source, 520, 78),
                       "full": derivative(source, 1800, 86), **extra})

    for row in references:
        assert sha(ROOT / row["package_path"]) == row["sha256"]
        add(row["id"], row["package_path"], row["title"], "targets", "2D-Nutzerziel · keine Modellabnahme",
            row["description"] + " " + row["limits"], origin=row["origin"], source_original_path=row["source_path"])
    for row in pack["pairs"]:
        add("before_" + row["id"], row["before"], "Vorher · Pass05 · " + row["title"], "before",
            "Native Godot-Aufnahme · bytegleicher Pass05-Vorherstand", "Gesicherter Ausgangsstand; derselbe Sichtzustand und dieselbe Kamera wie im P06-Paar.")
    names = dict(VIEWS)
    names.update(outpost="Außenposten / Schnitt", baseline="Farbprofil aus", walk_pose="Crew / Gehpose",
                 utility="Versorgung", cutlass_front="Cutlass / vorn", cutlass_rear="Cutlass / Heck",
                 buccaneer_front="Buccaneer / vorn", buccaneer_rear="Buccaneer / Heck")
    for row in pack["captures"]:
        view = row["id"]
        description = "Tatsächlicher P06-Stand. Geometrisches Relief bleibt auf gesperrte Felszonen begrenzt; die Materialroute ist bewusst Gegenstand der Revision. Technische Prüfung ist keine gestalterische Nutzerannahme."
        if view.startswith(("cutlass_", "buccaneer_")):
            description = "Kontrollansicht der unveränderten, weiter kritisierten R02-Schiffsmodelle in der neuen Umgebung. Kein neuer Schiffsmodellpass und keine automatische Astra-Adoption."
        elif view == "walk_pose":
            description = "Momentaufnahme einer laufenden Gehpose mit unveränderten GLBs/Clips. Keine zeitsynchrone Vorher-/Nachher-Animationsprüfung; diese Kontrollansicht gehört nicht zu den zwölf festen Paaren."
        add("after_" + view, row["path"], "Pass06 · " + names.get(view, view), "after",
            "Native Godot-Aufnahme · " + ("festes Vergleichspaar" if view in names and view in dict(VIEWS) else "zusätzliche Kontrollansicht außerhalb der zwölf Paare"),
            description, paired=view in dict(VIEWS), view=view)
    verification = read(PACKAGE / "pass06_environment_verification_manifest.json")
    assert verification["report_revision"] == REVISION and verification["code_commit_pushed"] is True
    assert verification["after_capture_sha256"] == sha(PACKAGE / "pass06_environment_after_capture.json")
    assert len(verification["pairs"]) == 12
    for row in verification["capture_records"]:
        assert sha(ROOT / row["path"]) == row["sha256"]
    for name, package in pack["source_packages"].items():
        assert verification["source_packages"][name]["sha256"] == package["sha256"]
    validation = read(PACKAGE / "report_validation.json")
    return {"report_id": REPORT_ID, "revision": REVISION, "assets": assets, "pairs": pack["pairs"],
            "targets": [row["id"] for row in references], "verification": verification,
            "source_packages": pack["source_packages"], "after_metadata": pack["after_metadata"],
            "before_metadata": pack["before_metadata"], "archive_sha256": ARCHIVE_SHA,
            "technical": [
                ["Problem", "Ebener Boden, große glatte Felsflächen und saubere Materialfelder bleiben zu weit von den Illustrationen entfernt."],
                ["Ursache", "Fehlende mittlere und kleine Erosion, kaum geometrische Randablagerungen und wenig gerichteter Pigment-/Gebrauchsabrieb."],
                ["Änderung", "Relief an geschützten Felsfüßen, feinere Erosion und überarbeitete Boden-/Fels-/Gebäudematerialien. Zwölf reale Pass05/Pass06-Paare bei gleicher Kamera und gleichem globalem Licht."],
                ["Betroffene Dateien", "Geologie, eigener Gebäude-Wearshader und Hüllenmaterialien, Boden-/Kontaktshader, Preview/Captures sowie diese begrenzte Offline-Workbench."],
                ["Risiken / offene Punkte", "Relief bleibt in bestehenden gesperrten Geologiehüllen. Begehbare Zentren, Wege, Pads und Höhen-/LOS-Fakten werden nicht zu frei modelliertem Gelände. Illustrationen bleiben reicher; keine allgemeine Performance-/Release-Abnahme."],
                ["Lokale Prüfung", validation.get("pass06_environment_local_checks", "Siehe den aktuellen versionsgebundenen Prüfmanifest-Link.")],
                ["Git-Status / Commit / Push", validation.get("pass06_environment_git_status", "Der native Commit ist im Prüfmanifest nachgewiesen; keine Main-Integration behauptet.")],
            ]}


